import React, { useState } from 'react';

const TavilyAPI = () => {
  const [userInput, setUserInput] = useState('');
  const [response, setResponse] = useState(null);
  const [error, setError] = useState(null);
  const [langchainResponse, setLangchainResponse] = useState(null); // LangChain 응답 상태 추가

  const testApi = async () => {
    const tivilyApiUrl = 'https://api.tavily.com/search';
    const tivilyApiKey = process.env.REACT_APP_TIVILY_API_KEY;

    try {
      const res = await fetch(tivilyApiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${tivilyApiKey}`,
        },
        body: JSON.stringify({
          query: userInput,
          api_key: tivilyApiKey,
          search_depth: 'basic',
          topic: 'general',
          max_results: 1,
          include_images: false,
        }),
      });

      if (!res.ok) {
        const errorData = await res.json();
        console.error('응답 오류 데이터:', errorData);
        throw new Error(errorData.detail || 'API 호출 실패');
      }

      const data = await res.json();
      setResponse(data);
      console.log('API 응답 성공:', data);

      // LangChain을 사용하여 질문에 대한 답변 생성
      const answer = await getLangChainResponse(userInput);
      setLangchainResponse(answer);

    } catch (err) {
      console.error('API 호출 실패:', JSON.stringify(err, null, 2));
      setError(err.message);
    }
  };

  // LangChain을 사용해 OpenAI 응답을 생성하는 함수
  const getLangChainResponse = async (question) => {
    const model = new OpenAI({
      apiKey: process.env.REACT_APP_OPENAI_API_KEY, // OpenAI API 키
    });

    try {
      const response = await model.call(question);
      return response.text; // 응답 텍스트 반환
    } catch (error) {
      console.error('LangChain 호출 실패:', error);
      return 'LangChain 응답 생성 중 오류가 발생했습니다.';
    }
  };

  return (
    <div>
      <h1>Tivily API 테스트</h1>
      <input
        type="text"
        placeholder="질문 입력"
        value={userInput}
        onChange={(e) => setUserInput(e.target.value)}
      />
      <button onClick={testApi}>API 호출 테스트</button>
      {response && (
        <div>
          <h2>응답 데이터:</h2>
          <pre>{JSON.stringify(response, null, 2)}</pre>
        </div>
      )}
      {langchainResponse && (
        <div>
          <h2>LangChain 응답:</h2>
          <p>{langchainResponse}</p>
        </div>
      )}
      {error && (
        <div style={{ color: 'red' }}>
          <h2>에러 발생:</h2>
          <p>{error}</p>
        </div>
      )}
    </div>
  );
};

export default TavilyAPI;
